import math
n = int(input())
a = list(map(int, input().split(' ')))
ans = 360
for i in range(n):
	for j in range(n):
		if i <= j:
			total = 0
			for k in range(i, j + 1, 1):
				total += a[k]
			ans = min(ans, abs(360 - 2 * total))
		else:
			total = 0
			for k in range(i, -1, -1):
				total += a[k]
			for k in range(n - 1, j - 1, -1):
				total += a[k]
			ans = min(ans, abs(360 - 2 * total))
print(ans)

